"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Wildflower Hearts', 'author': 'Signature original', 'genre': 'Summer Love', 'chapters': [{'n': 1, 'title': 'Homecoming', 'text': "her colleague Priya met her at the station with a hug that smelled of the vineyard valley: salt, wildflowers, fresh bread. 'You look like you need pie,' her colleague Priya said, which was her colleague Priya's diagnosis for everything, and usually right.\n\nThat evening she walked to the shore, a pressed wildflower in her pocket. The sunset did what the vineyard valley sunsets always did: made her feel everything at once. She wasn't alone long.\n\nHe was there — the boy from that summer, grown into a man with the same laugh. Time folded. Kate Sullivan's heart, so carefully guarded, did something reckless: it hoped."}, {'n': 2, 'title': 'The Thing Remembered', 'text': "a pressed wildflower turned out to be a map of sorts: a letter never sent, a promise never kept. Kate Sullivan read it on the porch swing while the vineyard valley hummed around her, and cried the good kind of crying.\n\nThey talked until the shop closed, until the streetlights came on in the vineyard valley. Seventeen years of almosts poured out: the almost-letters, the almost-calls, the life they'd almost shared.\n\nher ex Daniel — the reason she'd left, the shadow over it all — was still there, in the past where it belonged. Kate Sullivan felt it loosen its grip. the heart knows first, she thought. Maybe. Just maybe."}, {'n': 3, 'title': 'Complications', 'text': "a pressed wildflower sat on her dresser, accusing and comforting by turns. She picked it up and finally understood what it was: not a map to the past, but permission for the future.\n\nHe — the bookshop man, the summer boy — went quiet. Not angry, just hurt, in the way of someone who's waited seventeen years and can wait no longer. Kate Sullivan felt the old panic rise: run, before it breaks.\n\nOf course it couldn't be simple. her ex Daniel reappeared — older, smoother, with apologies like gift wrap. 'I've changed,' her ex Daniel said, and for an hour Kate Sullivan almost believed it."}, {'n': 4, 'title': 'The Choice', 'text': 'He laughed through tears, the same laugh, and the sunset did its thing, and the vineyard valley held its breath again. This time nobody interrupted. This time they stayed.\n\nher colleague Priya cried at the news and denied it. The whole of the vineyard valley seemed to conspire in their happiness: the bookshop stayed open late, the bakery made a cake, the wildflowers bloomed on schedule.\n\nher ex Daniel left town with the gift wrap and the almosts. Kate Sullivan felt nothing but pity — and then not even that, because her arms were full of present tense.'}, {'n': 5, 'title': 'The Promise', 'text': "Late that night, on the shore, they stood where the boy and girl had stood. 'We made it,' he said. 'We were always going to,' she said, and believed it, the heart knowing first.\n\nthe heart knows first — Kate Sullivan wrote it in the new journal, the one for the next seventeen years. In the vineyard valley, under the stars, with love: the whole story, and only just beginning.\n\nThey danced on the porch to the mixtape — no, to a new playlist, because the past is a place to visit, not to live. Kate Sullivan had learned that at last."}, {'n': 6, 'title': 'Epilogue in Wildflowers', 'text': "her colleague Priya still diagnoses everything with pie. Her grandmother Rose's quilt is worn thin with love. her ex Daniel is a story they tell laughing, a ghost with no haunting left in it.\n\nthe heart knows first. In the vineyard valley, in the wildflowers, in the salt air, in every sunset: the whole story, still beginning, never ending.\n\nYears later, a pressed wildflower sits on the mantel still, a little faded, entirely cherished. The house is full of noise: children, dogs, her colleague Priya's children, the whole beautiful chaos of a life chosen."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

